      { word: "atmosphere", pos: "n.", meaning: "大氣層；氛圍", example: "Pollution released into the atmosphere can travel thousands of kilometers.", example_zh: "排放到大氣層中的污染物可以傳播數千公里。" },
      { word: "concentration", pos: "n.", meaning: "濃度；集中", example: "The concentration of sugar in the drink was too high.", example_zh: "飲料中糖的濃度太高了。" },
      { word: "consequences", pos: "n.", meaning: "後果；影響", example: "Not studying for the exam had serious consequences for his grades.", example_zh: "沒有備考對他的成績產生了嚴重的後果。" },
      { word: "acidic", pos: "adj.", meaning: "酸性的；含酸的", example: "Lemon juice is acidic and can damage tooth enamel over time.", example_zh: "檸檬汁是酸性的，長期飲用可能損害牙齒琺瑯質。" },
      { word: "drought", pos: "n.", meaning: "乾旱；旱災", example: "The long drought destroyed most of the crops in the region.", example_zh: "長期乾旱摧毀了該地區的大部分農作物。" },
      { word: "renewable", pos: "adj.", meaning: "可再生的；可更新的", example: "Wind and solar are examples of renewable energy sources.", example_zh: "風能和太陽能是可再生能源的例子。" },
      { word: "emissions", pos: "n.", meaning: "排放物；排放量", example: "The new law requires factories to reduce their carbon emissions.", example_zh: "新法律要求工廠減少碳排放。" }
