      { phrase: "far-reaching", meaning: "影響深遠的；廣泛的", example: "The invention of the internet had far-reaching effects on communication.", example_zh: "網際網路的發明對通訊產生了深遠的影響。" },
      { phrase: "contribute to", meaning: "對…有貢獻；導致", example: "Regular exercise contributes to better physical and mental health.", example_zh: "定期運動有助於促進身體和心理健康。" },
      { phrase: "play a role", meaning: "扮演角色；起到作用", example: "Diet and sleep both play a role in how well we concentrate.", example_zh: "飲食和睡眠都在我們的專注力上起著重要作用。" },
      { phrase: "on a global scale", meaning: "在全球範圍內", example: "Plastic pollution must be addressed on a global scale.", example_zh: "塑膠污染必須在全球範圍內加以解決。" }
